import json
from collections import Counter

VALID_TIPO = {"bug", "enhancement", "documentation"}
VALID_SUP = {"app", "CLI", "extension", "codex-web", "iOS"}
VALID_AREAS = {
    "windows-os", "sandbox", "app-server", "connectivity", "TUI", "session",
    "rate-limits", "tool-calls", "browser", "remote", "model-behavior",
    "performance", "mcp", "auth", "context", "subagent", "config", "computer-use"
}

with open("incidencias.jsonl") as f:
    src = [json.loads(line) for line in f]

all_rows = []
for b in range(1, 7):
    path = f"/tmp/opencode/batch_{b}.jsonl"
    with open(path) as f:
        lines = [json.loads(line) for line in f if line.strip()]
    print(f"batch_{b}: {len(lines)} rows")
    all_rows.extend(lines)

assert len(all_rows) == len(src) == 300, f"Length mismatch: {len(all_rows)}"

errors = []
for i, (s, r) in enumerate(zip(src, all_rows), 1):
    rid = r.get("id")
    sid = s["id"]
    if rid != sid:
        errors.append((i, f"id mismatch {rid} != {sid}"))
    if set(r.keys()) != {"id", "tipo", "superficie", "areas"}:
        errors.append((i, f"keys {r.keys()}"))
    if r["tipo"] not in VALID_TIPO:
        errors.append((i, "bad tipo"))
    if r["superficie"] not in VALID_SUP:
        errors.append((i, "bad sup"))
    if not isinstance(r["areas"], list) or len(r["areas"]) != len(set(r["areas"])):
        errors.append((i, "bad areas list"))
    for a in r["areas"]:
        if a not in VALID_AREAS:
            errors.append((i, f"bad area {a}"))

print("Validation errors:", len(errors), errors[:10])
print("Tipos:", Counter(r["tipo"] for r in all_rows))
print("Superficies:", Counter(r["superficie"] for r in all_rows))
